css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;
  --src-nata: #ec4899;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-stats {
  width: min(720px, 100%);
  display: grid; gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

.bs-stat {
  padding: 14px;
  border: 1px solid var(--border); border-radius: 10px;
  /* Mais escuro que o painel de propósito: o card é um buraco no painel, não
     um cartão flutuante — por isso não existe sombra. */
  background: var(--bg-base);
}

.bs-stat-topo { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.bs-stat-rotulo {
  font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted);
}
.bs-stat-ic { width: 14px; height: 14px; color: var(--text-muted); }

.bs-stat-valor {
  font-family: var(--fonte-titulo); font-size: 22px; font-weight: 600;
  letter-spacing: -0.02em; color: var(--text);
}

/* Só a variação muda de cor. O valor fica branco mesmo quando é despesa. */
.bs-stat-delta { margin-top: 4px; font-size: 11px; font-weight: 600; }
.bs-pos { color: var(--success); }
.bs-neg { color: var(--danger); }
.bs-neu { color: var(--warning); }
